<?php
namespace App\Application\Claims;
use App\Application\Shared\CanonicalJson;use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;use Illuminate\Support\Str;
final class ClaimCommandGuard{public function __construct(private CanonicalJson$json){}public function replay(string$tenant,string$type,string$key,array$input):?array{$r=DB::table('claim_command_receipts')->where(['tenant_id'=>$tenant,'command_type'=>$type,'idempotency_key'=>$key])->first();if(!$r)return null;if($r->request_hash!==$this->json->hash($input))throw ValidationException::withMessages(['idempotency_key'=>__('wave7.idempotency_conflict')]);return json_decode($r->response_snapshot,true,512,JSON_THROW_ON_ERROR);}public function store(string$tenant,string$type,string$key,string$aggregate,array$input,array$response):void{DB::table('claim_command_receipts')->insert(['id'=>(string)Str::uuid(),'tenant_id'=>$tenant,'command_type'=>$type,'idempotency_key'=>$key,'aggregate_id'=>$aggregate,'request_hash'=>$this->json->hash($input),'response_snapshot'=>json_encode($response,JSON_THROW_ON_ERROR),'created_at'=>now()]);}}
